<?php session_start();require 'admin_db.php';$uid=$_SESSION['userID']??'';$gid=$_GET['groupID']??'';if(!$uid)die('Please login.');if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['leave'])){mysqli_query($conn,"UPDATE student_joins_group SET leaveDate=CURDATE() WHERE groupID='".mysqli_real_escape_string($conn,$gid)."' AND student_UID='".mysqli_real_escape_string($conn,$uid)."' AND (leaveDate IS NULL OR leaveDate='0000-00-00')");mysqli_query($conn,"INSERT INTO group_messages(groupID,senderID,message,message_type) VALUES('".mysqli_real_escape_string($conn,$gid)."','".mysqli_real_escape_string($conn,$uid)."','A member left the group.','LEAVE')");}elseif(isset($_POST['goal'])){$s=mysqli_prepare($conn,'INSERT INTO group_weekly_goals(groupID,studentID,goal,week_start) VALUES(?,?,?,CURDATE()) ON DUPLICATE KEY UPDATE goal=VALUES(goal),completed=0');mysqli_stmt_bind_param($s,'sss',$gid,$uid,$_POST['goal']);mysqli_stmt_execute($s);}elseif(isset($_POST['done'])){mysqli_query($conn,"UPDATE group_weekly_goals SET completed=1 WHERE goalID=".(int)$_POST['goalID']);}elseif(isset($_POST['approve'])){$rid=(int)$_POST['requestID'];$s=mysqli_prepare($conn,'SELECT student_UID FROM group_join_requests WHERE requestID=? AND groupID=?');mysqli_stmt_bind_param($s,'is',$rid,$gid);mysqli_stmt_execute($s);$rq=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if($rq){$s=mysqli_prepare($conn,'INSERT INTO student_joins_group(groupID,student_UID,joindate,leaveDate) VALUES(?,?,CURDATE(),NULL)');mysqli_stmt_bind_param($s,'ss',$gid,$rq['student_UID']);mysqli_stmt_execute($s);mysqli_query($conn,"UPDATE group_join_requests SET status='APPROVED' WHERE requestID=$rid");}}} $members=mysqli_query($conn,"SELECT j.student_UID FROM student_joins_group j WHERE j.groupID='".mysqli_real_escape_string($conn,$gid)."' AND (j.leaveDate IS NULL OR j.leaveDate='0000-00-00')");$g=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM group_info WHERE groupID='".mysqli_real_escape_string($conn,$gid)."'"));$req=mysqli_query($conn,"SELECT * FROM group_join_requests WHERE groupID='".mysqli_real_escape_string($conn,$gid)."' AND status='PENDING'");$goals=mysqli_query($conn,"SELECT * FROM group_weekly_goals WHERE groupID='".mysqli_real_escape_string($conn,$gid)."' ORDER BY completed,studentID");$isCreator=$g&&$g['group_creator_uid']===$uid;?>
<!doctype html><html><head><title>Group Dashboard</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="top"><h1>Group <?=htmlspecialchars($gid)?></h1><a class="btn" href="mygroup.php">My Groups</a></div><div class="panel"><p>Subject: <b><?=htmlspecialchars($g['targeted_subjects']??'')?></b></p><h3>Members</h3><ul><?php while($m=mysqli_fetch_assoc($members)):?><li><?=$m['student_UID']?></li><?php endwhile;?></ul><?php if(!$isCreator):?><form method="post"><button class="danger" name="leave">Leave Group</button></form><?php endif;?></div><div class="panel"><h2>Weekly Study Goals</h2><form method="post"><input name="goal" placeholder="Your weekly target" required><button>Add/Update Goal</button></form><table><tr><th>Student</th><th>Goal</th><th>Done?</th><th>Action</th></tr><?php while($x=mysqli_fetch_assoc($goals)):?><tr><td><?=$x['studentID']?></td><td><?=htmlspecialchars($x['goal'])?></td><td><?=$x['completed']?'Finished':'Pending'?></td><td><?php if($x['studentID']===$uid&&!$x['completed']):?><form method="post"><input type="hidden" name="goalID" value="<?=$x['goalID']?>"><button name="done">✓</button></form><?php endif;?></td></tr><?php endwhile;?></table></div><?php if($isCreator):?><div class="panel"><h2>Wanna Join Requests</h2><table><tr><th>Student</th><th>Action</th></tr><?php while($x=mysqli_fetch_assoc($req)):?><tr><td><?=$x['student_UID']?></td><td><form method="post"><input type="hidden" name="requestID" value="<?=$x['requestID']?>"><button name="approve">Approve</button></form></td></tr><?php endwhile;?></table></div><?php endif;?></div></body></html>
